diff --git a/lib/parsedate.c b/lib/parsedate.c
index 9630a988b9..f7b1bcabf0 100644
--- a/lib/parsedate.c
+++ b/lib/parsedate.c
@@ -338,11 +338,12 @@ UNITTEST int checktz(const char *check, size_t len)
   if(len > 4)
     return -1;
   first = check[0];
-  if(first < 'A')
+  /* all zone names start with an uppercase letter */
+  if((first < 'A') || (first > 'Z'))
     return -1;
   if(len == 1) {
     /* short-cut single letter names */
-    if((first > 'Z') || (first == 'J'))
+    if(first == 'J')
       return -1; /* no such tz */
     return tzone[first - 'A'] * 60;
   }

diff --git a/lib/parsedate.c b/lib/parsedate.c
