   first = check[0];
-  /* all zone names start with an uppercase letter */
-  if((first < 'A') || (first > 'Z'))
+  if(first < 'A')
     return -1;
   if(len == 1) {
     /* short-cut single letter names */
@@ -363,8 +362,6 @@ UNITTEST int checktz(const char *check, size_t len)
     /* three-letter name */
     const struct tzinfo *what;
     struct tzinfo find;
-    if(first > 'Y')
-      return -1;
     find.tz = MKTZ(first, check[1], check[2], 0);
     what = bsearch(&find, tzthree, CURL_ARRAYSIZE(tzthree),
                    sizeof(tzthree[0]), tzcompare);
@@ -375,8 +372,6 @@ UNITTEST int checktz(const char *check, size_t len)
     /* four-letter name */
     const struct tzinfo *what;
     struct tzinfo find;
-    if(first > 'W')
-      return -1;
     find.tz = MKTZ(first, check[1], check[2], check[3]);
     what = bsearch(&find, tzfoura, CURL_ARRAYSIZE(tzfoura),
                    sizeof(tzfoura[0]), tzcompare);
